<script setup lang="ts">
import { ref, watch } from 'vue'
import WorkspaceHeader from '../components/WorkspaceHeader.vue'
import ReportPanels from '../components/ReportPanels.vue'
import EvidenceDiagnosisPanel from '../components/EvidenceDiagnosisPanel.vue'
import { useWorkspace } from '../composables/useWorkspace'
import { workspaceApi } from '../api/workspace'
import * as sample from '../api/preview'
import { errorMessage } from '../api/client'
import type { Report } from '../types/workspace'
const { courseId, preview, loading, error, run } = useWorkspace(), report = ref<Report>(), algorithm = ref('baseline'), message = ref(''), reply = ref(''), replyContext = ref(''), busy = ref(false)
function load() { report.value = undefined; message.value = ''; reply.value = ''; replyContext.value = ''; void run(() => preview.value ? Promise.resolve(sample.report) : workspaceApi.report(courseId.value, algorithm.value), data => report.value = data) }
watch([preview, algorithm], load, { immediate: true })
async function followup() { if (!message.value.trim()) return; busy.value = true; replyContext.value = ''; try { if (preview.value) { reply.value = '此处展示提问回复。界面预览不调用模型，也不更新画像。' } else { const result = await workspaceApi.followup(courseId.value, message.value); reply.value = result.message; replyContext.value = result.personalization ? `本次参考了模拟历史：${result.personalization.matched_knowledge_points.join('、')}` : '本次问题未匹配到相关薄弱点，未加入模拟学习历史。' } } catch (e) { reply.value = errorMessage(e) } finally { busy.value = false } }
</script>
<template><WorkspaceHeader :course-id="courseId" title="个人学习报告" v-model:preview="preview" :loading="loading || busy" :error="error" @reload="load" /><EvidenceDiagnosisPanel v-if="!preview" :course-id="courseId" /><section v-loading="loading" class="panel"><div class="toolbar"><h2>学习反馈</h2><el-select v-model="algorithm" :disabled="busy" aria-label="推荐算法" style="width:220px"><el-option label="基础推荐" value="baseline" /><el-option label="增强推荐（E7，待开发）" value="enhanced" /></el-select></div><p v-if="preview" class="muted">两种算法共用布局样例，尚未运行推荐算法或对比评测。</p><template v-if="report?.history_source === 'synthetic'"><el-alert title="以下正确率、错题和薄弱点是为演示编写的模拟学习历史，不是实际测验成绩；正式画像与推荐仍待开发。" type="warning" :closable="false" class="alert-space" /><h3>分章节学习历史</h3><article v-for="chapter in report.chapter_history" :key="chapter.title" class="knowledge-card"><div class="toolbar"><h3>{{ chapter.title }}</h3><el-tag v-if="chapter.high_error" type="danger">错误率较高</el-tag></div><el-progress :percentage="chapter.accuracy" /><p>正确率 {{ chapter.accuracy }}% · 错误率 {{ 100 - chapter.accuracy }}%</p><h4>错题</h4><p v-for="(wrong, i) in chapter.wrong_questions" :key="i">{{ wrong.stem }}<br /><span class="muted">模拟作答：{{ wrong.answer }} · {{ wrong.knowledge_point }}</span></p><h4>需要巩固的知识点</h4><p v-for="weak in chapter.weak_knowledge_points" :key="weak.name"><strong>{{ weak.name }}</strong>：{{ weak.learning_gap }}。建议练习：{{ weak.practice }}。</p></article></template><ReportPanels v-if="report && report.history_source !== 'synthetic'" :report="report"><template #resource="{ item }"><RouterLink v-if="item.resource_id" :to="{ path: `/courses/${courseId}/learn`, query: { resource: item.resource_id } }"><el-button text>前往学习</el-button></RouterLink></template></ReportPanels><el-empty v-else-if="!report" description="暂无可展示的学习报告" /></section><section class="panel followup-panel"><h2>向学习助手提问</h2><p class="muted">演示课程可结合当前问题与相关模拟错题生成学习建议；无关历史不会加入提示。真实诊断追问与画像更新仍待开发。</p><el-input v-model="message" type="textarea" :rows="3" maxlength="2000" aria-label="学习提问" /><el-button type="primary" :loading="busy" :disabled="!report || !message.trim()" @click="followup">发送问题</el-button><p v-if="replyContext" class="muted">{{ replyContext }}</p><p aria-live="polite">{{ reply }}</p></section></template>
